    if not line.strip():
        continue
    o = json.loads(line)
    t = o.get("type")
    data = o.get("data") or {}
    if t == "assistant/message":
        u = data.get("usage")
        if isinstance(u, dict):
            for k in u:
                usage_keys[k] = usage_keys.get(k, 0) + 1
            if "_sample" not in usage_keys:
                usage_keys["_sample"] = {k: u[k] for k in list(u)[:20]}
