        print("MSG_KEYS", list(msg.keys())[:20] if isinstance(msg, dict) else type(msg).__name__)
    if t == "tool/call":
        names[data.get("name")] = names.get(data.get("name"), 0) + 1
    if t == "tool/result":
        blob = json.dumps(data, ensure_ascii=False)
        found = re.findall(r"model=([^\s,;\"']+)", blob)
        if found:
            model_hits += len(found)
            if model_hits <= 8:
