"""Summarize host vs orchestrator model tokens from a DSH session.v4.jsonl.

Host tokens come from assistant/message data.usage, attributed to the model in
the latest request/header. Orchestrator models are regex-matched as model=...
inside tool/result text. Usage objects in the same tool result, if any, are
attributed to that model; a bare model= tag with no usage is counted as a hit
with unknown tokens.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from collections import defaultdict
from pathlib import Path

MODEL_RE = re.compile(r"model=([A-Za-z0-9_./:@+-]+)")
USAGE_RE = re.compile(
    r"\{[^\{\}]{0,400}?(?:inputTokens|prompt_tokens|uncachedInputTokens)[^\{\}]{0,400}?\}"
)


def _int(value) -> int:
    try:
        return int(value or 0)
    except (TypeError, ValueError):
        return 0


def _usage_from_obj(obj: dict) -> dict | None:
    if not isinstance(obj, dict):
        return None
    keys = (
        "inputTokens",
        "uncachedInputTokens",
        "outputTokens",
        "completion_tokens",
        "cacheReadTokens",
        "prompt_tokens",
        "totalTokens",
        "total_tokens",
    )
    if not any(k in obj for k in keys):
        return None
    uncached = _int(obj.get("uncachedInputTokens", obj.get("inputTokens", obj.get("prompt_tokens"))))
    output = _int(obj.get("outputTokens", obj.get("completion_tokens")))
    cache = _int(obj.get("cacheReadTokens"))
    total = _int(obj.get("totalTokens", obj.get("total_tokens")))
    if total == 0:
        total = uncached + output + cache
    return {
        "uncached": uncached,
        "cache_read": cache,
        "output": output,
        "total": total,
    }


def _text(value) -> str:
    if isinstance(value, str):
        return value
    return json.dumps(value, ensure_ascii=False)


def load(path: Path) -> list[dict]:
    events = []
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.strip():
            events.append(json.loads(line))
    return events


def summarize(events: list[dict]) -> dict:
    host_model = "unknown-host"
    calls: dict[str, str] = {}
    host = defaultdict(lambda: {"steps": 0, "uncached": 0, "cache_read": 0, "output": 0, "total": 0})
    spikes = []
    inner = defaultdict(lambda: {"hits": 0, "with_usage": 0, "uncached": 0, "cache_read": 0, "output": 0, "total": 0})
    pending_tools: list[str] = []

    for event in events:
        kind = event.get("type")
        data = event.get("data") or {}
        if kind == "request/header":
            header = data.get("header") or {}
            config = header.get("config") or {}
            host_model = config.get("model") or host_model
            continue
        if kind == "tool/call":
            calls[data.get("callId")] = data.get("name") or "?"
            pending_tools.append(data.get("name") or "?")
            continue
        if kind == "assistant/message":
            usage = _usage_from_obj(data.get("usage") or {})
            if not usage:
                continue
            bucket = host[host_model]
            bucket["steps"] += 1
            for key in ("uncached", "cache_read", "output", "total"):
                bucket[key] += usage[key]
            if usage["uncached"] >= 20000:
                spikes.append(
                    {
                        "seq": event.get("seq"),
                        "model": host_model,
                        "uncached": usage["uncached"],
                        "cache_read": usage["cache_read"],
                        "output": usage["output"],
                        "tools_since_prev": pending_tools[:],
                    }
                )
            pending_tools.clear()
            continue
        if kind != "tool/result":
            continue
        message = data.get("message") or {}
        call_id = message.get("toolCallId") if isinstance(message, dict) else None
        tool = calls.get(call_id, "?")
        text = _text(message.get("content") if isinstance(message, dict) else message)
        models = MODEL_RE.findall(text)
        usages = []
        for raw in USAGE_RE.findall(text):
            try:
                parsed = _usage_from_obj(json.loads(raw))
            except json.JSONDecodeError:
                parsed = None
            if parsed and parsed["total"]:
                usages.append(parsed)
        if not models:
            continue
        share = usages if len(usages) == len(models) else []
        for index, model in enumerate(models):
            bucket = inner[model]
            bucket["hits"] += 1
            bucket.setdefault("tools", defaultdict(int))
            bucket["tools"][tool] += 1
            if share:
                bucket["with_usage"] += 1
                for key in ("uncached", "cache_read", "output", "total"):
                    bucket[key] += share[index][key]
            elif len(models) == 1 and len(usages) == 1:
                bucket["with_usage"] += 1
                for key in ("uncached", "cache_read", "output", "total"):
                    bucket[key] += usages[0][key]
    return {"host": host, "inner": inner, "spikes": spikes}


def _fmt(bucket: dict) -> str:
    return (
        f"steps/hits={bucket.get('steps', bucket.get('hits', 0)):<4} "
        f"uncached={bucket['uncached']:<8} cache_read={bucket['cache_read']:<8} "
        f"output={bucket['output']:<6} total={bucket['total']}"
    )


def render(path: Path, report: dict) -> str:
    lines = [f"session: {path}", "", "host (assistant/message usage)"]
    if not report["host"]:
        lines.append("  (none)")
    for model, bucket in report["host"].items():
        lines.append(f"  {model}")
        lines.append(f"    {_fmt(bucket)}")
    lines.append("")
    lines.append("orchestrator (tool/result model=)")
    if not report["inner"]:
        lines.append("  (no model= tags)")
    for model, bucket in sorted(report["inner"].items()):
        tools = ", ".join(f"{name}:{count}" for name, count in bucket.get("tools", {}).items())
        known = "tokens known" if bucket["with_usage"] else "tokens not in log"
        lines.append(f"  {model}  hits={bucket['hits']}  {known}  via {tools}")
        if bucket["with_usage"]:
            lines.append(f"    {_fmt(bucket)}")
    if report["spikes"]:
        lines.append("")
        lines.append("host steps with uncached input >= 20000")
        for spike in report["spikes"]:
            tools = ", ".join(spike["tools_since_prev"]) or "-"
            lines.append(
                f"  seq={spike['seq']} uncached={spike['uncached']} "
                f"cache_read={spike['cache_read']} output={spike['output']} tools={tools}"
            )
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("jsonl", type=Path)
    args = parser.parse_args(argv)
    report = summarize(load(args.jsonl))
    sys.stdout.write(render(args.jsonl, report) + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
